// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// Where the explorer draws its own controls on a 1600x720 phone, landscape, in canvas units ([x, y, width, height]
// from the top left); other phones scale them with the screen. Nothing reports their real rects, so they are
// computed the way the mobile client (godot-explorer) lays them out: the top-left buttons row is measured from the
// mobile preview, the action buttons follow its joypad.gd/joypad_arc.gd. The HUD layout places itself around them
// and the editor's mobile check measures against the same numbers.
export type PhoneRect = [number, number, number, number]

export const PHONE_SCREEN = { width: 1600, height: 720 }
export const PHONE_SCREEN_INSET = { left: 108, top: 32, right: 108, bottom: 45 }
export const PHONE_EXPLORER_BUTTONS: PhoneRect = [108, 32, 360, 85]
// where the chat opens when the player taps it; the interactable area starts right of it
export const PHONE_CHAT_COLUMN: PhoneRect = [108, 117, 328, 558]
export const PHONE_JOYSTICK: PhoneRect = [177, 444, 170, 170]
export const PHONE_JOYSTICK_ZONE: PhoneRect = [0, 240, 640, 480]
// the right and bottom screen insets the action buttons sit against, the large button, the arc discs and their orbit
export const PHONE_ACTION_CLUSTER = { right: 108, bottom: 45, large: 156, small: 80, orbit: 167 }

const GAP = 12
/** The HUD's left column on a phone: at the left screen inset, below the explorer's buttons row, above the joystick. */
export const PHONE_LEFT_COLUMN = {
  left: PHONE_SCREEN_INSET.left,
  top: PHONE_EXPLORER_BUTTONS[1] + PHONE_EXPLORER_BUTTONS[3] + GAP,
  bottom: PHONE_JOYSTICK[1] - GAP
}

/** A length along the phone's width or height as a share of the screen, for a layout drawn over the whole screen. */
export function phoneShare(value: number, of: 'width' | 'height'): `${number}%` {
  return `${Math.round(value / PHONE_SCREEN[of] * 10000) / 100}%`
}
